  if(p==='/sales' && method==='GET'){ const db=await getDb(); const limit=Math.max(1,Math.min(Number(u.searchParams.get('pageSize')||100),500)); const status=u.searchParams.get('status')||''; const q=String(u.searchParams.get('search')||'').trim(); const where=["(?='' OR s.status=?)","(?='' OR s.invoice_no LIKE ? OR COALESCE(c.name,'') LIKE ?)"]; const params:any[]=[status,status,q,`%${q}%`,`%${q}%`]; if(user!.role==='cashier'){where.push('s.user_id=?');params.push(user!.id)} const rows=query<any>(db,`SELECT s.*,s.date date,s.created_at createdAt,c.name customerName,c.phone customerPhone,u.name userName,(SELECT COUNT(*) FROM sale_items i WHERE i.sale_id=s.id) itemsCount FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.user_id WHERE ${where.join(' AND ')} ORDER BY s.date DESC LIMIT ${limit}`,params); return jsonResponse({items:rows.map((x:any)=>({...x,customer:x.customerName?{name:x.customerName,phone:x.customerPhone||null}:null,user:x.userName?{name:x.userName}:null,date:x.date||x.createdAt||null}))}) }
  if(p==='/products' && method==='GET'){ return jsonResponse(await listProductsResponse(u)) }
  const pm2=p.match(/^\/products\/([^/]+)$/); if(pm2){ const id=pm2[1]; const db=await getDb(); if(method==='GET'){ const row=mapProduct(db,id); return row?jsonResponse(row):jsonResponse({error:'غير موجود'},404)} if(method==='PATCH'){ if(!['admin','manager'].includes(user!.role))return jsonResponse({error:'صلاحية غير كافية'},403); const b=await body(req); const existing=mapProduct(db,id); if(!existing)return jsonResponse({error:'غير موجود'},404); if(Array.isArray(b.variants)){const incoming=b.variants;const skus=incoming.map((v:any)=>String(v.sku||'').trim()); if(skus.some((x:string)=>!x)||new Set(skus).size!==skus.length)return jsonResponse({error:'SKUs غير صحيحة أو مكررة'},400); const conflicts=query<any>(db,`SELECT sku FROM product_variants WHERE sku IN (${skus.map(()=>'?').join(',')}) AND product_id<>?`,[...skus,id]); if(conflicts.length)return jsonResponse({error:`SKU مكرر لمنتج آخر: ${conflicts.map((x:any)=>x.sku).join(', ')}`},400)} await withTransaction(db=>{ const keys=['name','description','categoryId','brandId','gender','season','material','image']; const set:any[]=[]; const vals:any[]=[]; for(const k of keys)if(b[k]!==undefined){set.push(`${k.replace(/[A-Z]/g,m=>'_'+m.toLowerCase())}=?`);vals.push(b[k])} if(set.length){ vals.push(id); run(db,`UPDATE products SET ${set.join(',')},updated_at=datetime('now') WHERE id=?`,vals)} if(Array.isArray(b.variants)){ const old=query<any>(db,'SELECT id FROM product_variants WHERE product_id=?',[id]); const ids=new Set(b.variants.filter((v:any)=>v.id).map((v:any)=>v.id)); for(const o of old)if(!ids.has(o.id)){const used=query<any>(db,`SELECT 1 WHERE EXISTS(SELECT 1 FROM sale_items WHERE variant_id=?) OR EXISTS(SELECT 1 FROM purchase_items WHERE variant_id=?) OR EXISTS(SELECT 1 FROM stock_movements WHERE variant_id=?)`,[o.id,o.id,o.id]); if(used.length)throw new Error('لا يمكن حذف Variant مرتبط بحركة تاريخية'); run(db,'DELETE FROM product_variants WHERE id=?',[o.id]);} for(const v of b.variants){ const data=[v.sku,v.barcode||null,v.size||null,v.color||null,v.material||null,Number(v.costPrice||0),Number(v.sellPrice||0),Number(v.minQuantity||0),Number(v.reorderQty||0),v.baseUnit||'piece',v.purchaseUnit||'piece',Number(v.purchaseUnitFactor||1),v.saleUnit||'piece',Number(v.saleUnitFactor||1),v.quarterDozenPrice??null,v.halfDozenPrice??null,v.dozenPrice??null]; if(v.id&&query<any>(db,'SELECT id FROM product_variants WHERE id=? AND product_id=?',[v.id,id]).length){ run(db,`UPDATE product_variants SET sku=?,barcode=?,size=?,color=?,material=?,cost_price=?,sell_price=?,min_quantity=?,reorder_qty=?,base_unit=?,purchase_unit=?,purchase_unit_factor=?,sale_unit=?,sale_unit_factor=?,quarter_dozen_price=?,half_dozen_price=?,dozen_price=?,updated_at=datetime('now') WHERE id=?`,[...data,v.id]) } else run(db,`INSERT INTO product_variants(id,product_id,sku,barcode,size,color,material,cost_price,sell_price,quantity,min_quantity,reorder_qty,base_unit,purchase_unit,purchase_unit_factor,sale_unit,sale_unit_factor,quarter_dozen_price,half_dozen_price,dozen_price) VALUES(?,?,?,?,?,?,?,?,?,0,?,?,?,?,?,?,?,?,?,?,?)`,[uuid(),id,...data]) } } }); return jsonResponse(mapProduct(db,id)) } if(method==='DELETE'){ const activity=query<any>(db,'SELECT 1 FROM product_variants v WHERE v.product_id=? AND (EXISTS(SELECT 1 FROM sale_items s WHERE s.variant_id=v.id) OR EXISTS(SELECT 1 FROM purchase_items p WHERE p.variant_id=v.id)) LIMIT 1',[id]); if(activity.length)return jsonResponse({error:'لا يمكن حذف المنتج لأنه مرتبط بحركة تاريخية'},400); run(db,'DELETE FROM products WHERE id=?',[id]); await (await import('./db/client')).persist(); return jsonResponse({success:true}) } }
